import { NativeModules, Vibration, Platform } from 'react-native';
const { VibrateModule } = NativeModules;
export const vibrate = (ms) => {
  if (VibrateModule?.vibrate) VibrateModule.vibrate(ms);
  else if (Platform.OS !== 'web' && Vibration?.vibrate) Vibration.vibrate(ms);
};
